  /** Resolve a 5-digit (state+county) FIPS to a friendly "Travis County, Texas" string. */
  export function fipsToFriendly(fips5: string, jurisdictionsByCode?: Record<string,{name:string}>): string {
    const c = FIPS_TO_COUNTY[fips5];
    if (!c) return fips5;
    if (jurisdictionsByCode && jurisdictionsByCode[c.state]) {
      return `${c.name}, ${jurisdictionsByCode[c.state].name}`;
    }
    return `${c.name}, ${c.state}`;
  }

  /** Look up a county by its 3-digit code within a state (e.g. resolveCountyInState("TX","021") → "Bastrop County"). */
  export function resolveCountyInState(stateUSPS: string, countyFips3: string): string | undefined {
    const padded = countyFips3.padStart(3, "0");
    return COUNTIES_BY_STATE[stateUSPS]?.find(c => c.countyFips === padded)?.name;
  }
  